como posso melhorar esse meu código?

<?php
// Conexão com o banco de dados
require 'db_connect.php';

// Função para criar uma cláusula IN segura
function createInClause($column, $values, $conn, &$types, &$params) {
    if (empty($values)) {
        return "1"; // Sempre verdadeiro se não houver valores
    }
    $placeholders = implode(',', array_fill(0, count($values), '?'));
    $types .= str_repeat('s', count($values));
    foreach ($values as $value) {
        $params[] = $value;
    }
    return "$column IN ($placeholders)";
}

// Buscar GREs
$gres = $conn->query("SELECT DISTINCT gre FROM turmas WHERE gre LIKE 'GRE%' ORDER BY gre");

// Inicializar variáveis
$escolas = null;
$professores = null;
$turmas = null;
$turma_info = [];

// Preparar a consulta para escolas se GREs forem selecionados
if (isset($_GET['gre']) && !empty($_GET['gre'])) {
    $selected_gres = $_GET['gre'];
    // Criar cláusula IN para GREs
    $types = '';
    $params = [];
    $gre_clause = createInClause('gre', $selected_gres, $conn, $types, $params);
    $stmt = $conn->prepare("SELECT DISTINCT escola FROM turmas WHERE $gre_clause ORDER BY escola");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($gre_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $escolas = $stmt->get_result();
    $stmt->close();
}

// Preparar a consulta para professores e turmas se escolas forem selecionadas
if (isset($_GET['escola']) && !empty($_GET['escola'])) {
    $selected_escolas = $_GET['escola'];
    // Criar cláusula IN para escolas
    $types = '';
    $params = [];
    $escola_clause = createInClause('escola', $selected_escolas, $conn, $types, $params);

    // Buscar professores
    $stmt = $conn->prepare("SELECT DISTINCT professor FROM turmas WHERE $escola_clause ORDER BY professor");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($escola_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $professores = $stmt->get_result();
    $stmt->close();

    // Buscar turmas
    $stmt = $conn->prepare("SELECT id, turma FROM turmas WHERE $escola_clause ORDER BY turma");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($escola_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $turmas = $stmt->get_result();
    $stmt->close();
}

// Preparar a consulta para turmas específicas se professores forem selecionados
if (isset($_GET['professor']) && !empty($_GET['professor']) && isset($_GET['escola']) && !empty($_GET['escola'])) {
    $selected_professores = $_GET['professor'];
    $selected_escolas = $_GET['escola'];
    // Criar cláusula IN para professores e escolas
    $types = '';
    $params = [];
    $professor_clause = createInClause('professor', $selected_professores, $conn, $types, $params);
    $escola_clause = createInClause('escola', $selected_escolas, $conn, $types, $params);
    $combined_clause = "$professor_clause AND $escola_clause";
    $stmt = $conn->prepare("SELECT id, turma FROM turmas WHERE $combined_clause ORDER BY turma");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($professor_clause !== "1" && $escola_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $turmas = $stmt->get_result();
    $stmt->close();
}

// Função para determinar quais turmas buscar com base nos filtros
function determineTurmas($conn, $filters) {
    $gre = isset($filters['gre']) ? $filters['gre'] : [];
    $escola = isset($filters['escola']) ? $filters['escola'] : [];
    $professor = isset($filters['professor']) ? $filters['professor'] : [];
    $turma = isset($filters['turma']) ? $filters['turma'] : [];

    // Inicializar variáveis
    $types = '';
    $params = [];
    $where_clauses = [];

    if (!empty($turma)) {
        // Se turmas estão selecionadas, buscar apenas elas
        $turma_clause = createInClause('id', $turma, $conn, $types, $params);
        $where_clauses[] = $turma_clause;
    } else {
        if (!empty($professor)) {
            // Se professores estão selecionados, buscar turmas desses professores
            $professor_clause = createInClause('professor', $professor, $conn, $types, $params);
            $where_clauses[] = $professor_clause;
        }

        if (!empty($escola)) {
            // Se escolas estão selecionadas, buscar turmas dessas escolas
            $escola_clause = createInClause('escola', $escola, $conn, $types, $params);
            $where_clauses[] = $escola_clause;
        }

        if (!empty($gre)) {
            // Se GREs estão selecionados, buscar turmas desses GREs
            $gre_clause = createInClause('gre', $gre, $conn, $types, $params);
            $where_clauses[] = $gre_clause;
        }
    }

    // Montar a cláusula WHERE
    $where = '';
    if (!empty($where_clauses)) {
        $where = 'WHERE ' . implode(' AND ', $where_clauses);
    }

    // Preparar e executar a consulta
    $sql = "SELECT * FROM turmas $where";
    $stmt = $conn->prepare($sql);
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }

    if (!empty($params)) {
        $stmt->bind_param($types, ...$params);
    }

    $stmt->execute();
    $result = $stmt->get_result();
    $stmt->close();

    // Retornar os resultados
    return $result;
}

// Determinar quais turmas buscar com base nos filtros
if (isset($_GET['gre']) || isset($_GET['escola']) || isset($_GET['professor']) || isset($_GET['turma'])) {
    $filters = [
        'gre' => isset($_GET['gre']) ? $_GET['gre'] : [],
        'escola' => isset($_GET['escola']) ? $_GET['escola'] : [],
        'professor' => isset($_GET['professor']) ? $_GET['professor'] : [],
        'turma' => isset($_GET['turma']) ? $_GET['turma'] : []
    ];

    $result = determineTurmas($conn, $filters);
    if ($result && $result->num_rows > 0) {
        // Armazenar todas as informações das turmas
        while ($row = $result->fetch_assoc()) {
            $turma_info[] = $row;
        }
    }
}

$conn->close();
