    <script>
        $(document).ready(function() {
            // Inicializa o Select2 com tema Bootstrap
            $('#gre, #escola, #professor, #turma').select2({
                theme: 'bootstrap-5',
                placeholder: '--Selecione--',
                allowClear: true
            });

            // Função para lidar com "Selecionar Tudo"
            function handleSelectAll(element) {
                element.on('select2:select', function(e) {
                    if (e.params.data.id === 'all') {
                        let allOptions = element.find('option').map(function() { return $(this).val(); }).get();
                        // Remover 'all' da lista
                        allOptions = allOptions.filter(function(value) { return value !== 'all'; });
                        element.val(allOptions).trigger('change');
                    }
                });

                element.on('select2:unselect', function(e) {
                    if (e.params.data.id === 'all') {
                        // Não fazer nada quando 'all' é desmarcado
                        // Isso impede que o backend trate 'all' como uma opção válida
                    }
                });
            }

            // Aplicar a função aos selects
            handleSelectAll($('#gre'));
            handleSelectAll($('#escola'));
            handleSelectAll($('#professor'));
            handleSelectAll($('#turma'));

            // Lógica para habilitar/desabilitar campos com base nas seleções
            $('#gre').change(function() {
                if ($(this).val() && $(this).val().length > 0) {
                    $('#escola').prop('disabled', false);
                } else {
                    $('#escola').prop('disabled', true).val(null).trigger('change');
                    $('#professor').prop('disabled', true).val(null).trigger('change');
                    $('#turma').prop('disabled', true).val(null).trigger('change');
                }
                $('#filtroForm').submit();
            });

            $('#escola').change(function() {
                if ($(this).val() && $(this).val().length > 0) {
                    $('#professor').prop('disabled', false);
                } else {
                    $('#professor').prop('disabled', true).val(null).trigger('change');
                    $('#turma').prop('disabled', true).val(null).trigger('change');
                }
                $('#filtroForm').submit();
            });

            $('#professor').change(function() {
                if ($(this).val() && $(this).val().length > 0) {
                    $('#turma').prop('disabled', false);
                } else {
                    $('#turma').prop('disabled', true).val(null).trigger('change');
                }
                $('#filtroForm').submit();
            });

            $('#turma').change(function() {
                $('#filtroForm').submit();
            });

            // Lidar com o envio do formulário configForm via AJAX com spinner de progresso
            $('#configForm').submit(function(e) {
                e.preventDefault();

                // Exibir o spinner de carregamento
                $('#loading').show();

                $.ajax({
                    url: $(this).attr('action'),
                    method: 'POST',
                    data: $(this).serialize(),
                    success: function(response) {
                        // Ocultar o spinner de carregamento
                        $('#loading').hide();
                        // Exibir o resultado
                        $('#configResult').html(response);
                    },
                    error: function() {
                        // Ocultar o spinner de carregamento
                        $('#loading').hide();
                        // Exibir mensagem de erro
                        $('#configResult').html('<div class="alert alert-danger">Erro ao carregar os links.</div>');
                    }
                });
            });
        });
    </script>
</body>
